pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy with owner = address(this)
        address owner = address(this);
        vm.deal(owner, 1 ether);
        // Send 0.5 ether via sendMoney to a random address (0xdead)
        vm.prank(owner);
        c.sendMoney(address(0xdead), 0.5 ether);
        // Now the contract balance is exactly 0.5 ether (the msg.value sent to fallback is 0, but sendMoney sends ether)
        // Call withdrawAll
        vm.prank(owner);
        c.withdrawAll();
        // After withdrawAll, reference: contract balance becomes 0, owner gets 0.5 ether
        // Bug: withdrawAll does nothing, contract still has 0.5 ether, owner balance unchanged
        // Assert on the observable state: c.owner() should equal address(this) (the owner) in reference; bug makes it different? Actually owner never changes, but withdrawAll observable difference is that the contract balance equals 0 (reference) vs 0.5 ether (bug)
        // We use address(c).balance
        assertTrue(address(c).balance == 0, "Reference: contract balance should be 0 after withdrawAll");
    }
}

