pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 1 wei}("");
        assertTrue(success);
        uint initialBalance = address(c).balance;
        vm.prank(nonOwner);
        try c.sendMoney(nonOwner, 0) {
            // should revert in reference, succeed in buggy
            // In reference, non-owner cannot call sendMoney -> revert; in buggy, it succeeds
            // After buggy sendMoney, balance unchanged (value=0), but depositsCount incremented? Actually sendMoney doesn't increment depositsCount, only fallback does.
            // The difference is that reference reverts, buggy does not.
            // Use the fact that after sendMoney, the reference would have reverted, so we only reach here in buggy case -> fail the test.
            assertTrue(false);
        } catch {
            // Reference reverts, success.
            assertTrue(true);
        }
    }
}

