pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner sends 1 ether to the contract itself via sendMoney
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.sendMoney(address(this), 1 ether);

        // In the reference, withdraw() returns 0 because the call sends to msg.sender (the owner) but the balance is sent to the contract?
        // Actually, the reference's withdraw(uint _value) does payable(msg.sender).transfer(_value);
        // sendMoney(address(this), 1 ether) calls withdraw(uint256) from within? No, sendMoney directly calls _target.call{value: _value}("");
        // The difference stated: after sendMoney(...), P.withdraw() != M.withdraw(). 
        // Since in the reference, withdraw() returns 0 (no withdrawals happened), and in the buggy, withdraw() returns address(this).balance (since the buggy withdraw function sends to address(this)).
        // But sendMoney doesn't call withdraw. The divergence is that the buggy withdraw function sends to address(this) instead of msg.sender, so when sendMoney is called, it doesn't affect withdraw(). 
        // Wait: the bug is in withdraw(uint _value). sendMoney is called; it doesn't call withdraw. 
        // The difference must be that after sendMoney, the value of state variable withdraw differs? 
        // Actually, withdraw is a public view function that returns the contract's balance? No, withdraw is a function, not a state variable. 
        // The contract has no public state variable named "withdraw". The only public state variables are owner and depositsCount.
        // The problem statement says: "the value of state variable `withdraw` differs: P.withdraw() != M.withdraw()". 
        // But withdraw is a function, not a state variable. Possibly they mean the function withdraw returns different values? 
        // Let's re-read: "after a call to `sendMoney(...)` completes, the value of state variable `withdraw` differs". 
        // There is no state variable withdraw. This is confusing.
        // Given the test must be concrete, I'll assume that the observable difference is via a public getter of a state variable that doesn't exist. 
        // But to satisfy the requirement, I need an assertion that holds on reference and fails on bug. 
        // The simplest: after sendMoney to self, the contract's balance increases. The reference's withdraw function would send that balance to msg.sender if called, but we don't call withdraw. 
        // The buggy withdraw function sends to address(this), which would double the balance. But again, we don't call withdraw.
        // The only way to observe a difference without calling withdraw is if there is a public state variable that tracks something related. 
        // But there isn't. Perhaps the intended difference is that in the buggy version, calling withdraw sends to itself, so the contract's balance remains unchanged after withdraw; in the reference, balance decreases. 
        // But the test must call sendMoney and then observe something. 
        // Given the constraints, I'll assert that the contract's balance after sendMoney is 1 ether, and the reference's withdraw() (if it were a getter) would return 0, but it's not. 
        // Alternatively, I can call c.withdraw(0) after sendMoney? But the buggy withdraw sends to address(this), so it would revert if _value > address(this).balance? No, it would send to itself, so it would add to balance.
        // Let's construct a scenario: owner calls sendMoney(address(this), 1 ether). Then owner calls c.withdraw(1 ether). In reference, balance decreases; in buggy, balance increases (or stays same?). 
        // The buggy: payable(address(this)).transfer(_value) sends 1 ether to itself, net zero change. Actually it sends to itself, so balance remains unchanged. So after withdraw(1 ether), reference balance = initial - 1, buggy balance = initial (since it sent to itself). 
        // So if initial balance is 1 ether (from sendMoney), reference balance becomes 0, buggy balance remains 1. 
        // Therefore I can assert address(c).balance == 0 for reference, and == 1 ether for buggy.
        // That works.
        // But the problem says "after a call to sendMoney(...) completes", not after withdraw. 
        // To meet the wording, I'll do sendMoney(address(this), 1 ether) then immediately call c.withdraw(1 ether) and then check balance.

        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.sendMoney(address(this), 1 ether);

        vm.prank(address(this));
        c.withdraw(1 ether);

        // In reference, balance should be 0; in buggy, balance should be 1 ether (since sendMoney gave 1, and withdraw sent to itself, net 1).
        assertTrue(address(c).balance == 0 ether, "Balance should be zero in reference");
    }
}

