pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        uint256 initialOwnerBalance = owner.balance;
        uint256 oneEth = 1 ether;
        vm.deal(owner, initialOwnerBalance + oneEth);
        vm.deal(address(c), 0);

        // Owner sends 1 ether to the contract via sendMoney
        c.sendMoney{value: oneEth}(address(this), oneEth);

        // Owner tries to withdraw 1 ether
        uint256 balanceBeforeWithdraw = owner.balance;
        c.withdraw(oneEth);
        uint256 balanceAfterWithdraw = owner.balance;

        // In the reference, owner receives the ether; in the buggy version, owner receives nothing
        assertTrue(balanceAfterWithdraw == balanceBeforeWithdraw + oneEth, "Owner should have received ether");
    }
}

